<template><div class="page"><div class="page-head"><div><h1 class="page-title">个人中心</h1><div class="page-sub">管理个人资料与账号安全</div></div></div><div class="profile-grid"><el-card class="identity"><div class="avatar-wrap"><el-avatar :size="88">{{user.realName?.slice(0,1)||'管'}}</el-avatar><span></span></div><h2>{{user.realName}}</h2><p>@{{user.username}}</p><el-tag type="success">{{role}}</el-tag><el-divider/><div class="info"><p><el-icon><Phone/></el-icon>{{user.phone||'未填写'}}</p><p><el-icon><Message/></el-icon>{{user.email||'未填写'}}</p><p><el-icon><Clock/></el-icon>账号状态正常</p></div></el-card><el-card><template #header><b>基本资料</b></template><el-form label-position="top"><div class="form-grid"><el-form-item label="真实姓名"><el-input v-model="user.realName"/></el-form-item><el-form-item label="用户名"><el-input v-model="user.username" disabled/></el-form-item><el-form-item label="手机号"><el-input v-model="user.phone"/></el-form-item><el-form-item label="电子邮箱"><el-input v-model="user.email"/></el-form-item></div><el-form-item label="个人简介"><el-input type="textarea" :rows="4" placeholder="介绍一下自己"/></el-form-item><el-button type="primary" @click="save">保存修改</el-button></el-form><el-divider/><h3>账号安全</h3><div class="safe"><div><b>登录密码</b><small>建议定期修改密码，保障账号安全</small></div><el-button>修改密码</el-button></div></el-card></div></div></template><script setup lang="ts">import{reactive,computed}from'vue';import{ElMessage}from'element-plus';const user=reactive(JSON.parse(localStorage.getItem('user')||'{}'));const role=computed(()=>({ADMIN:'系统管理员',LIBRARIAN:'图书管理员',READER:'读者'}as any)[user.roleCode]);function save(){localStorage.setItem('user',JSON.stringify(user));ElMessage.success('资料保存成功')}</script><style scoped>.profile-grid{display:grid;grid-template-columns:300px 1fr;gap:18px}.identity{text-align:center;padding-top:22px}.avatar-wrap{position:relative;display:inline-block}.avatar-wrap span{position:absolute;width:15px;height:15px;background:#3bc88d;border:3px solid #fff;border-radius:50%;right:4px;bottom:5px}.identity h2{margin:15px 0 5px}.identity>p{color:#9aa5b2;margin:0 0 14px}.info{text-align:left}.info p{display:flex;align-items:center;gap:10px;color:#657589;font-size:13px}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 18px}.safe{display:flex;justify-content:space-between;align-items:center;padding:12px 0}.safe small{display:block;color:#96a2b1;margin-top:6px}</style>

